"""
Nonlinear Leg (Leg 2 of Ensemble):
Direct Multi-Horizon LightGBM Quantile Regression (P10, P50, P90)
Global Horizon-Conditioned Model with Strict Training Cutoff (s + h <= t_0)
"""

from __future__ import annotations

import logging
import time
from datetime import date, timedelta
from typing import Dict, List, Optional, Tuple
import lightgbm as lgb
import numpy as np
import pandas as pd

logger = logging.getLogger("coffee_tracker_ml.lgbm_quant")

# Canonical feature column names generated by build_causal_features
MODEL_FEATURE_COLS = [
    "log_ret_1w",
    "log_ret_4w",
    "log_ret_12w",
    "log_ret_26w",
    "log_ret_52w",
    "vol_4w",
    "vol_12w",
    "vol_26w",
    "basis_vnd_kg",
    "calendar_spread",
    "brent_log_ret_4w",
    "sin_month",
    "cos_month",
    "oni_lag_12w",
    "oni_lag_26w",
    "rainfall_anomaly_daklak_lag_12w",
    "rainfall_anomaly_daklak_lag_26w",
    "rainfall_anomaly_linhares_lag_12w",
    "rainfall_anomaly_linhares_lag_26w",
]

# Quantiles for probabilistic fan chart
QUANTILES = [0.10, 0.50, 0.90]


def prepare_training_dataset(
    df_features: pd.DataFrame,
    max_h: int = 26,
    warmup_weeks: int = 52,
) -> Tuple[pd.DataFrame, pd.Series, List[Tuple[pd.Timestamp, int, pd.Timestamp]]]:
    """
    Stacks historical training observations into a global horizon-conditioned dataset.
    ENFORCES STRICT CUTOFF LEAKAGE RULE:
    For any historical origin date s and horizon h in 1..max_h:
    The target date s_target = s + h weeks.
    Only include sample (X_s, h, y_{s+h}) IF target date s_target is within the observed index!
    (i.e. s_idx + h < total_rows).
    """
    y_raw = df_features["price_daklak"].values
    log_y = np.log(y_raw)
    T = len(df_features)

    # Available feature columns present in df_features
    avail_cols = [c for c in MODEL_FEATURE_COLS if c in df_features.columns]

    X_rows = []
    y_rows = []
    audit_trail = []  # stores (origin_date, h, target_date) for audit

    # Loop over all historical origins s after warmup
    for s_idx in range(warmup_weeks, T):
        origin_dt = df_features.index[s_idx]
        x_base = df_features.iloc[s_idx][avail_cols].to_dict()

        for h in range(1, max_h + 1):
            target_idx = s_idx + h
            # Strict Cutoff Rule: Target must be observed before or at origin t_0 (T - 1)
            if target_idx < T:
                target_dt = df_features.index[target_idx]
                target_log_ret = float(log_y[target_idx] - log_y[s_idx])

                row_dict = dict(x_base)
                row_dict["horizon_week"] = h

                X_rows.append(row_dict)
                y_rows.append(target_log_ret)
                audit_trail.append((origin_dt, h, target_dt))

    df_X = pd.DataFrame(X_rows)
    s_y = pd.Series(y_rows, name="target_log_ret")

    return df_X, s_y, audit_trail


def train_lightgbm_quantile_models(
    X_train: pd.DataFrame,
    y_train: pd.Series,
    quantiles: List[float] = QUANTILES,
    random_state: int = 42,
) -> Dict[float, lgb.Booster]:
    """
    Trains 3 conservative LightGBM quantile regression models (alpha = 0.1, 0.5, 0.9).
    Uses core LightGBM C++ API (lgb.train) for maximum execution speed and zero overhead.
    """
    dtrain = lgb.Dataset(X_train, label=y_train, free_raw_data=False)
    models = {}

    for alpha in quantiles:
        params = {
            "objective": "quantile",
            "alpha": alpha,
            "metric": "quantile",
            "learning_rate": 0.05,
            "max_depth": 4,
            "num_leaves": 15,
            "min_child_samples": 20,
            "subsample": 0.8,
            "colsample_bytree": 0.8,
            "random_state": random_state,
            "verbosity": -1,
            "n_jobs": -1,
        }
        booster = lgb.train(params, dtrain, num_boost_round=100)
        models[alpha] = booster

    return models


def lgbm_quantile_forecast(
    df_features: pd.DataFrame,
    origin_date: date,
    horizon_weeks: int = 26,
    random_state: int = 42,
) -> Tuple[pd.DataFrame, float]:
    """
    Generates 26-week probabilistic forecast using Global Horizon-Conditioned LightGBM.
    Returns:
    - Standardized DataFrame with columns [horizon_week, target_date, log_ret_p10, log_ret_p50, log_ret_p90, pred_p10, pred_p50, pred_p90]
    - Elapsed runtime in seconds.
    """
    t_start = time.perf_counter()

    # 1. Prepare training dataset with strict cutoff rule
    X_train, y_train, _ = prepare_training_dataset(df_features, max_h=horizon_weeks)

    if len(X_train) < 100:
        raise ValueError(f"Insufficient training samples ({len(X_train)}) for LightGBM Quantile regression")

    # 2. Train 3 quantile models
    models = train_lightgbm_quantile_models(X_train, y_train, quantiles=QUANTILES, random_state=random_state)

    # 3. Build inference matrix at origin t_0
    latest_row = df_features.iloc[-1]
    origin_price = float(latest_row["price_daklak"])
    avail_cols = [c for c in MODEL_FEATURE_COLS if c in df_features.columns]

    x_origin = latest_row[avail_cols].to_dict()

    inference_rows = []
    for h in range(1, horizon_weeks + 1):
        row = dict(x_origin)
        row["horizon_week"] = h
        inference_rows.append(row)

    df_inference = pd.DataFrame(inference_rows)

    # 4. Predict P10, P50, P90 of log return
    raw_p10 = models[0.10].predict(df_inference)
    raw_p50 = models[0.50].predict(df_inference)
    raw_p90 = models[0.90].predict(df_inference)

    rows = []
    for h in range(1, horizon_weeks + 1):
        idx = h - 1
        target_date = origin_date + timedelta(weeks=h)

        # Monotonicity enforcement on predicted log return
        ret_p10, ret_p50, ret_p90 = sorted([float(raw_p10[idx]), float(raw_p50[idx]), float(raw_p90[idx])])

        # Reconstruct price levels: Y_t * exp(log_ret)
        price_p10 = float(round(origin_price * np.exp(ret_p10), 2))
        price_p50 = float(round(origin_price * np.exp(ret_p50), 2))
        price_p90 = float(round(origin_price * np.exp(ret_p90), 2))

        # Enforce price monotonicity and bounds
        price_p10, price_p50, price_p90 = sorted([price_p10, price_p50, price_p90])
        price_p10 = max(price_p10, 10000.0)

        rows.append(
            {
                "horizon_week": h,
                "target_date": target_date,
                "log_ret_p10": float(round(ret_p10, 6)),
                "log_ret_p50": float(round(ret_p50, 6)),
                "log_ret_p90": float(round(ret_p90, 6)),
                "pred_p10": price_p10,
                "pred_p50": price_p50,
                "pred_p90": price_p90,
                "model_type": "LIGHTGBM_QUANTILE_GLOBAL",
            }
        )

    df_forecast = pd.DataFrame(rows)
    elapsed_sec = time.perf_counter() - t_start
    logger.info(f"LightGBM Quantile forecast completed in {elapsed_sec:.2f} seconds")

    return df_forecast, elapsed_sec
